"use strict";
// Code download and two-way GitHub sync for Create projects. The export is a
// standard Vite + React + Tailwind project; its 'kairoq' import points at the
// app's backend on this Kairoq server.
const fs=require('fs'),path=require('path');
const builder=require('./react-builder'),assets=require('./react-assets');

const MANAGED=/^(src\/|functions\/|sql\/|public\/uploads\/|index\.html$|package\.json$|vite\.config\.js$|tailwind\.config\.js$|postcss\.config\.js$|capacitor\.config\.json$|\.github\/workflows\/kairoq-android\.yml$|README\.md$|\.gitignore$)/;
function fail(status,message){return Object.assign(Error(message),{status})}
function slug(name){return String(name||'app').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,60)||'app'}
function publicOrigin(){return(process.env.KAIROQ_PUBLIC_URL||(process.env.RAILWAY_PUBLIC_DOMAIN?'https://'+process.env.RAILWAY_PUBLIC_DOMAIN:'')).replace(/\/$/,'')}

// react and react-dom plus every allowed package the source imports, at Kairoq's pinned versions.
function usedDependencies(source,pkg){
 const deps={react:pkg.react,'react-dom':pkg['react-dom']};
 for(const code of Object.values(source))for(const m of String(code).matchAll(/(?:from|import)\s*\(?\s*['"]([^'".][^'"]*)['"]/g)){
  const spec=m[1];if(spec==='kairoq')continue;
  const name=spec.startsWith('@')?spec.split('/').slice(0,2).join('/'):spec.split('/')[0];
  if(pkg[name])deps[name]=pkg[name];
 }
 return Object.fromEntries(Object.entries(deps).sort());
}
// The app's public web address, used by the native app for Google sign-in and reset links.
function appUrl(meta){const u=require('./react-hosting').siteUrls(meta);return u?(u.domains[0]||u.subdomain||u.path):''}
function exportFiles(id){
 const meta=builder.loadMeta(id);
 if(!meta.current_version)throw fail(409,'Build the app first');
 const source=builder.loadFiles(id,meta.current_version),pkg=require('./package.json').dependencies;
 const out={
  'package.json':JSON.stringify({name:slug(meta.name),private:true,version:'1.0.0',type:'module',scripts:{dev:'vite',build:'vite build',preview:'vite preview'},
   dependencies:usedDependencies(source,pkg),
   devDependencies:{vite:pkg.vite,'@vitejs/plugin-react':pkg['@vitejs/plugin-react'],tailwindcss:pkg.tailwindcss}},null,2)+'\n',
  'vite.config.js':"import { defineConfig } from 'vite';\nimport react from '@vitejs/plugin-react';\nimport { fileURLToPath } from 'node:url';\n\nexport default defineConfig({\n  base: './',\n  plugins: [react()],\n  resolve: { alias: { kairoq: fileURLToPath(new URL('./src/kairoq.js', import.meta.url)) } }\n});\n",
  'tailwind.config.js':"export default {\n  content: ['./index.html', './src/**/*.{js,jsx,ts,tsx}'],\n  // Colours, fonts, radius and shadows come from the CSS variables in src/index.css.\n  theme: "+JSON.stringify(require('./react-design').THEME,null,2).replace(/\n/g,'\n  ')+",\n  plugins: []\n};\n",
  'postcss.config.js':"import tailwind from 'tailwindcss';\n\nexport default { plugins: [tailwind()] };\n",
  'index.html':builder.INDEX_HTML.replace('    <script type="module" src="/kairoq-reporter.js"></script>\n',''),
  '.gitignore':'node_modules\ndist\n',
  'README.md':'# '+meta.name+'\n\nBuilt with Kairoq Create.\n\n```\nnpm install\nnpm run dev\n```\n\nThe app\'s backend (sign-in, saved data, files, email, payments) stays on Kairoq. `src/kairoq.js` connects to it at '+(publicOrigin()||'your Kairoq server')+'.\nEdit files under `src/` and push to GitHub; use **Pull from GitHub** in Kairoq to bring changes back.\n',
  ...source,
  'src/kairoq.js':'// Generated by Kairoq. Connects this app to its Kairoq backend.\n'+require('./react-backend').clientSource(id,publicOrigin(),0,appUrl(meta))
 };
 for(const a of assets.list(id)){const f=assets.read(id,a.name);if(f)out['public/uploads/'+a.name]=f.bytes}
 // Mobile setting: a Capacitor iOS/Android project plus an Android APK workflow for GitHub.
 const mobile=require('./react-mobile');
 if(mobile.settings(meta).enabled){
  Object.assign(out,mobile.nativeFiles(meta,out['package.json']));
  out['index.html']=out['index.html'].replace('width=device-width, initial-scale=1.0','width=device-width, initial-scale=1.0, viewport-fit=cover');
  out['README.md']+=mobile.nativeReadme(meta);
 }
 return out;
}
function zip(id){return require('./project-portability').zip(exportFiles(id))}

// ---------- GitHub ----------
async function gh(token,pathname,{method='GET',body}={}){
 const r=await fetch('https://api.github.com'+pathname,{method,headers:{Authorization:'Bearer '+token,Accept:'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28','User-Agent':'Kairoq-Create',...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(30000)});
 const data=r.status===204?{}:await r.json().catch(()=>({}));
 if(!r.ok)throw Object.assign(fail(r.status===401||r.status===403?403:r.status===404?404:502,'GitHub: '+(data.message||r.status)),{github:r.status});
 return data;
}
function token(id,{isOwner}){
 const t=require('./project-secrets').get(id,'github_token')||(isOwner?process.env.GITHUB_TOKEN:null);
 if(!t)throw fail(409,'Add a GitHub token in Settings first (fine-grained, with Contents read and write)');
 return t;
}
function normalizeRepo(repo){const r=String(repo||'').trim().replace(/^https:\/\/github\.com\//,'').replace(/\.git$/,'').replace(/\/$/,'');if(!/^[A-Za-z0-9-]+\/[A-Za-z0-9._-]+$/.test(r))throw fail(400,'Repository must look like owner/name');return r}
async function ensureRepo(t,repo){
 try{return await gh(t,'/repos/'+repo)}
 catch(e){
  if(e.github!==404)throw e;
  const [owner,name]=repo.split('/');
  const me=await gh(t,'/user');
  const created=await gh(t,me.login.toLowerCase()===owner.toLowerCase()?'/user/repos':'/orgs/'+owner+'/repos',{method:'POST',body:{name,private:true,auto_init:true,description:'Built with Kairoq Create'}});
  return created;
 }
}
// Writing .github/workflows needs a token with the Workflows permission. Without it, push
// everything else and say how to enable the Android build.
const WORKFLOW='.github/workflows/kairoq-android.yml';
async function push(id,opts){
 try{return await pushOnce(id,opts,false)}
 catch(e){
  if(!/workflow/i.test(String(e.message))||!Object.hasOwn(exportFiles(id),WORKFLOW))throw e;
  const r=await pushOnce(id,opts,true);
  return{...r,warning:'Pushed without the Android build workflow: give the GitHub token the "Workflows: read and write" permission and push again to get an APK on every push.'};
 }
}
async function pushOnce(id,{repo,isOwner},skipWorkflow){
 const meta=builder.loadMeta(id),t=token(id,{isOwner}),full=normalizeRepo(repo||meta.github?.repo);
 const info=await ensureRepo(t,full),branch=info.default_branch||'main';
 const ref=await gh(t,'/repos/'+full+'/git/ref/heads/'+branch);
 const head=await gh(t,'/repos/'+full+'/git/commits/'+ref.object.sha);
 const base=await gh(t,'/repos/'+full+'/git/trees/'+head.tree.sha+'?recursive=1');
 const files=exportFiles(id);
 if(skipWorkflow)delete files[WORKFLOW];
 const tree=(base.tree||[]).filter(e=>e.type==='blob'&&(!MANAGED.test(e.path)||skipWorkflow&&e.path===WORKFLOW)).map(e=>({path:e.path,mode:e.mode,type:'blob',sha:e.sha}));
 for(const [p,content] of Object.entries(files)){
  const blob=await gh(t,'/repos/'+full+'/git/blobs',{method:'POST',body:Buffer.isBuffer(content)?{content:content.toString('base64'),encoding:'base64'}:{content,encoding:'utf-8'}});
  tree.push({path:p,mode:'100644',type:'blob',sha:blob.sha});
 }
 const newTree=await gh(t,'/repos/'+full+'/git/trees',{method:'POST',body:{tree}});
 if(newTree.sha===head.tree.sha)return{repo:full,branch,commit:head.sha,unchanged:true,url:'https://github.com/'+full};
 const commit=await gh(t,'/repos/'+full+'/git/commits',{method:'POST',body:{message:'Kairoq: version '+meta.current_version+' of '+meta.name,tree:newTree.sha,parents:[head.sha]}});
 await gh(t,'/repos/'+full+'/git/refs/heads/'+branch,{method:'PATCH',body:{sha:commit.sha}});
 const fresh=builder.loadMeta(id);fresh.github={repo:full,branch,last_push:{sha:commit.sha,version:meta.current_version,at:new Date().toISOString()},last_pull:fresh.github?.last_pull||null};builder.saveMeta(fresh);
 return{repo:full,branch,commit:commit.sha,url:'https://github.com/'+full+'/commit/'+commit.sha};
}
// Brings src/ changes made on GitHub back as a new version.
async function pull(id,{isOwner}){
 const meta=builder.loadMeta(id);
 if(!meta.github?.repo)throw fail(409,'Push to GitHub first');
 const t=token(id,{isOwner}),full=meta.github.repo,branch=meta.github.branch||'main';
 const ref=await gh(t,'/repos/'+full+'/git/ref/heads/'+branch);
 const head=await gh(t,'/repos/'+full+'/git/commits/'+ref.object.sha);
 const tree=await gh(t,'/repos/'+full+'/git/trees/'+head.tree.sha+'?recursive=1');
 const wanted=(tree.tree||[]).filter(e=>e.type==='blob'&&(e.path.startsWith('src/')&&e.path!=='src/kairoq.js'||/^functions\/[a-z][a-z0-9-]{0,39}\.js$/.test(e.path)||/^sql\/\d{3}_[a-z0-9_]{1,40}\.sql$/.test(e.path)));
 if(wanted.length>80)throw fail(400,'Too many files under src/');
 const files={};
 for(const e of wanted){
  if(e.size>200000)throw fail(400,e.path+' is larger than 200 KB');
  const blob=await gh(t,'/repos/'+full+'/git/blobs/'+e.sha);
  files[e.path]=Buffer.from(blob.content||'','base64').toString('utf8');
 }
 const current=builder.loadFiles(id,meta.current_version);
 const changed=[...new Set([...Object.keys(files),...Object.keys(current)])].filter(k=>files[k]!==current[k]);
 if(!changed.length)return{unchanged:true,commit:head.sha};
 const result=await builder.saveSource(id,files,{summary:'Pulled from GitHub '+full+'@'+head.sha.slice(0,7),changed});
 const fresh=builder.loadMeta(id);fresh.github={...fresh.github,last_pull:{sha:head.sha,version:result.version,at:new Date().toISOString()}};builder.saveMeta(fresh);
 return{...result,commit:head.sha,changed};
}
module.exports={exportFiles,zip,push,pull,normalizeRepo,MANAGED};
